  if (response.status === 401) throw new IdentityError('未取得有效登录会话，请从当前平台重新打开应用后重试。', 'unauthenticated');
  if (response.status === 403) throw new IdentityError('当前账号无权读取身份信息，请联系平台管理员。', 'forbidden');
